const fs=require('fs'),path=require('path'),cp=require('child_process'),crypto=require('crypto');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/pages/home-overlays/before-after-preview.css',IMPORTER='assets/css/pages/home-overlays.css',RUNTIME_PAGE='assets/css/pages/home-runtime-page.css',RUNTIME='assets/css/pages/home-runtime.css',PAGE_MANIFEST='assets/css/pages/home.css',PAGE='index.html';
const SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB,widths=[360,379,380,381,559,560,561,679,680,681,760,979,980,981,1280,1440];
const sh=c=>cp.execSync(c,{encoding:'utf8'}).trim(),assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
function importsFor(file,tracked){const src=fs.readFileSync(file,'utf8'),out=[],re=/@import\s+(?:url\()?['"]?([^'"\);]+\.css(?:\?[^'"\)]*)?)['"]?\)?/gi;let m;while((m=re.exec(src))){let v=m[1].replace(/\?.*$/,'').replace(/^\.\//,'');if(v.startsWith('/'))v=v.replace(/^\/+/, '');else if(!v.startsWith('assets/'))v=path.posix.normalize(path.posix.join(path.posix.dirname(file),v));if(tracked.has(v))out.push(v);}return out;}
function verifyReach(){const report=JSON.parse(fs.readFileSync('reports/generated/active-legacy-structures-report.json','utf8')),tracked=new Set(cp.execFileSync('git',['ls-files','-z','assets/css'],{encoding:'utf8'}).split('\0').filter(f=>f.endsWith('.css')));const direct=sh("git grep -l -F 'before-after-preview.css?v=' -- assets/css || true").split(/\r?\n/).filter(Boolean).sort();assert(JSON.stringify(direct)===JSON.stringify([IMPORTER]),'direct importer drift '+JSON.stringify(direct));assert(importsFor(IMPORTER,tracked).includes(TARGET),'overlay manifest drift');assert(importsFor(RUNTIME_PAGE,tracked).includes(IMPORTER),'runtime-page drift');assert(importsFor(RUNTIME,tracked).includes(RUNTIME_PAGE),'runtime drift');assert(importsFor(PAGE_MANIFEST,tracked).includes(RUNTIME),'home manifest drift');const html=fs.readFileSync(PAGE,'utf8');assert((html.match(/data-before-after-preview\b/g)||[]).length>=1,'overlay markup missing');const pages=[];for(const page of report.pageAssets){const seen=new Set(),stack=[...(page.css||[]).filter(f=>tracked.has(f))];let hit=false;while(stack.length){const f=stack.pop();if(seen.has(f)||!tracked.has(f))continue;seen.add(f);if(f===TARGET){hit=true;break;}for(const n of importsFor(f,tracked))stack.push(n);}if(hit)pages.push(page.page);}assert(JSON.stringify(pages.sort())===JSON.stringify([PAGE]),'reach pages '+JSON.stringify(pages));console.log(`REACH AUTHORITY PASS|chain=${PAGE}->${PAGE_MANIFEST}->${RUNTIME}->${RUNTIME_PAGE}->${IMPORTER}->${TARGET}|pages=1`);}
function verify(p){assert(p.declarations.length===436,'decl '+p.declarations.length);assert(p.dead.length===17,'dead '+p.dead.length);assert(new Set(p.dead.map(d=>d.selector)).size===9,'selectors drift');const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===3,'identical '+identical);console.log('DEAD ROWS PASS|decl=436|dead=17|selectors=9|identical=3|changed=14');}
async function capture(browser,tag){const out={};for(const width of widths){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),p=await ctx.newPage();await p.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort();});await p.goto(`http://127.0.0.1:4173/index.html?${tag}-${width}-${Date.now()}`,{waitUntil:'networkidle',timeout:20000});await p.evaluate(()=>{document.querySelector('[data-doke-document-preloader]')?.remove();document.body.classList.add('before-after-preview-open');const o=document.querySelector('[data-before-after-preview]');if(!o)throw new Error('missing overlay');o.hidden=false;o.setAttribute('aria-hidden','false');});await p.waitForTimeout(250);out[width]=await p.evaluate(()=>{const pick=(s,ps)=>{const e=document.querySelector(s);if(!e)throw new Error('missing '+s);const c=getComputedStyle(e),r=e.getBoundingClientRect(),o={};for(const k of ps)o[k]=c[k];o.rect=[r.x,r.y,r.width,r.height].map(n=>Math.round(n*1000)/1000);return o};return{overlay:pick('.before-after-preview',['display','position','zIndex','paddingTop','paddingRight','paddingBottom','paddingLeft']),dialog:pick('.before-after-preview__dialog',['width','maxHeight','borderRadius','backgroundColor','backgroundImage','overflow']),stage:pick('.before-after-preview__stage',['display','gridTemplateColumns','gridTemplateRows','minHeight']),mediaShell:pick('.before-after-preview__media-shell',['display','paddingTop','paddingRight','paddingBottom','paddingLeft']),mediaCard:pick('.before-after-preview__media-card',['display','gridTemplateRows','paddingTop','paddingRight','paddingBottom','paddingLeft','borderRadius','backgroundColor']),media:pick('.before-after-preview__media',['display','minHeight','height']),stats:pick('.before-after-preview__stats',['display','gridTemplateColumns','rowGap','columnGap']),stat:pick('.before-after-preview__stat',['paddingTop','paddingRight','paddingBottom','paddingLeft','borderRadius']),panel:pick('.before-after-preview__panel',['display','paddingTop','paddingRight','paddingBottom','paddingLeft','overflow']),mediaQueries:{max560:matchMedia('(max-width:560px)').matches,max680:matchMedia('(max-width:680px)').matches,max980:matchMedia('(max-width:980px)').matches},doc:{cw:document.documentElement.clientWidth,sw:document.documentElement.scrollWidth,bcw:document.body.clientWidth,bsw:document.body.scrollWidth}}});assert(out[width].doc.sw<=out[width].doc.cw,'overflow '+tag+' '+width);await ctx.close();}return out;}
function apply(p){const src=fs.readFileSync(TARGET,'utf8'),had=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(had&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(d.property+':'),'line mismatch '+d.line);lines.splice(d.line-1,1);}fs.writeFileSync(TARGET,lines.join('\n')+(had?'\n':''));const n=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(n[0]==='0'&&n[1]==='17'&&n[2]===TARGET,'delta '+n.join('/'));const a=parse(fs.readFileSync(TARGET,'utf8'));assert(a.declarations.length===419&&a.dead.length===0,`after ${a.declarations.length}/${a.dead.length}`);return crypto.createHash('sha256').update(fs.readFileSync(TARGET)).digest('hex');}
(async()=>{assert(sh('git rev-parse HEAD')===SHA,'wrong sha');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');verifyReach();const src=fs.readFileSync(TARGET,'utf8'),beforeBytes=Buffer.byteLength(src),parsed=parse(src);verify(parsed);const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});const before=await capture(browser,'before'),hash=apply(parsed),afterBytes=Buffer.byteLength(fs.readFileSync(TARGET)),after=await capture(browser,'after');await browser.close();assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');assert(sh('git diff --name-only -- assets index.html resultados.html')===TARGET,'product scope drift');console.log(`CANDIDATE BUILD PASS|hash=${hash}|bytes=${beforeBytes}->${afterBytes}|files=1|additions=0|deletions=17|decl=436->419|dead=17->0`);console.log(`CANDIDATE RUNTIME PASS|viewports=${widths.join(',')}|computed+rect+document/body=0-diffs|overflow=0|boundaries=560/680/980|page=${PAGE}`);fs.writeFileSync('/tmp/ux-css-debt-032-candidate-hash',hash+'\n');fs.writeFileSync('/tmp/ux-css-debt-032-candidate-bytes',String(afterBytes)+'\n');}finally{server.kill('SIGTERM');}})().catch(e=>{console.error(e.stack||e);try{cp.execSync(`git reset --hard ${SHA} && git clean -fdx`,{stdio:'inherit'})}catch{}process.exit(1)});